ugly-number:
class Solution:
    def isUgly(self, n: int) -> bool:
        if n <= 0: return False
        for p in (2, 3, 5):
            while n % p == 0:
                n //= p
        return n == 1

summary-ranges:
class Solution:
    def summaryRanges(self, nums: List[int]) -> List[str]:
        res = []
        i = 0
        while i < len(nums):
            start = nums[i]
            while i+1 < len(nums) and nums[i+1] == nums[i]+1:
                i += 1
            if start != nums[i]:
                res.append(f"{start}->{nums[i]}")
            else:
                res.append(str(start))
            i += 1
        return res

