longest-palindrome:
class Solution:
    def longestPalindrome(self, s: str) -> int:
        from collections import Counter
        c = Counter(s)
        length = 0
        has_odd = False
        for v in c.values():
            length += v // 2 * 2
            if v % 2: has_odd = True
        return length + (1 if has_odd else 0)

convert-a-number-to-hexadecimal:
class Solution:
    def toHex(self, num: int) -> str:
        if num == 0: return "0"
        if num < 0:
            num += 2**32
        h = "0123456789abcdef"
        res = ""
        while num:
            res = h[num % 16] + res
            num //= 16
        return res

