degree-of-an-array:
class Solution:
    def findShortestSubArray(self, nums: List[int]) -> int:
        first, last, count = {}, {}, {}
        for i, x in enumerate(nums):
            if x not in first: first[x] = i
            last[x] = i
            count[x] = count.get(x, 0) + 1
        deg = max(count.values())
        return min(last[x]-first[x]+1 for x in count if count[x] == deg)

count-binary-substrings:
class Solution:
    def countBinarySubstrings(self, s: str) -> int:
        groups = []
        cur = 1
        for i in range(1, len(s)):
            if s[i] == s[i-1]: cur += 1
            else:
                groups.append(cur); cur = 1
        groups.append(cur)
        return sum(min(groups[i], groups[i+1]) for i in range(len(groups)-1))

image-smoother:
class Solution:
    def imageSmoother(self, img: List[List[int]]) -> List[List[int]]:
        R, C = len(img), len(img[0])
        res = [[0]*C for _ in range(R)]
        for i in range(R):
            for j in range(C):
                total, cnt = 0, 0
                for di in (-1,0,1):
                    for dj in (-1,0,1):
                        ni, nj = i+di, j+dj
                        if 0 <= ni < R and 0 <= nj < C:
                            total += img[ni][nj]; cnt += 1
                res[i][j] = total // cnt
        return res

maximum-average-subarray-i:
class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        cur = sum(nums[:k])
        best = cur
        for i in range(k, len(nums)):
            cur += nums[i] - nums[i-k]
            best = max(best, cur)
        return best / k

