n-ary-tree-preorder-traversal:
"""
# Definition for a Node.
class Node:
    def __init__(self, val=None, children=None):
        self.val = val
        self.children = children
"""
class Solution:
    def preorder(self, root):
        res = []
        def dfs(node):
            if not node: return
            res.append(node.val)
            for c in node.children: dfs(c)
        dfs(root)
        return res

